arguments.file_text:
@using sv_d6ddb3952d904867be27d6d70fce2d54.Services

<div class="channel-list">
    <div class="channel-list-header">
        <h5>Channels</h5>
    </div>
    <div class="channel-list-items">
        @foreach (var channel in Channels)
        {
            <button class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
                    @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-name-row">
                    <span class="channel-name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrWhiteSpace(channel.Description))
                {
                    <span class="channel-description">@Truncate(channel.Description, 40)</span>
                }
            </button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.channel-list {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #2b2d31;
    color: #b5bac1;
}

.channel-list-header {
    padding: 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.channel-list-header h5 {
    margin: 0;
    color: #f2f3f5;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.channel-list-items {
    flex: 1;
    overflow-y: auto;
    padding: 8px;
}

.channel-item {
    display: block;
    width: 100%;
    background: none;
    border: none;
    border-radius: 4px;
    padding: 8px 10px;
    margin-bottom: 2px;
    text-align: left;
    color: #b5bac1;
    cursor: pointer;
    transition: background-color 0.1s;
}

.channel-item:hover {
    background-color: #35373c;
    color: #f2f3f5;
}

.channel-item.active {
    background-color: #404249;
    color: #f2f3f5;
}

.channel-name-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

.channel-item.active .channel-name,
.unread-badge ~ .channel-name {
    font-weight: 600;
}

.unread-badge {
    background-color: #f23f43;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 8px;
    min-width: 18px;
    text-align: center;
}

.channel-description {
    display: block;
    font-size: 0.75rem;
    color: #80848e;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

