@using sv_d6ddb3952d904867be27d6d70fce2d54.Services

<div class="message-area">
    <div class="message-area-header">
        <h5># @ChannelName</h5>
        @if (!string.IsNullOrWhiteSpace(ChannelDescription))
        {
            <span class="header-description">@ChannelDescription</span>
        }
    </div>

    <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
        @if (_loadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ThreadReplyCount="GetThreadReplyCount(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-input"
                  rows="1"
                  placeholder="Message #@ChannelName"
                  @bind="_newMessage"
                  @onkeydown="HandleKeyDown" />
        <button class="send-btn" disabled="@string.IsNullOrWhiteSpace(_newMessage)" @onclick="SendMessage">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private string _newMessage = "";
    private bool _loadingMore;
    private ElementReference _messageListRef;

    private int GetThreadReplyCount(int messageId)
    {
        var summary = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);
        return summary?.ReplyCount ?? 0;
    }

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading older messages.
        // We use a JS-free approach: the parent handles pagination state.
        // This fires on any scroll; the parent debounces/gates via its own flag.
        await OnLoadMore.InvokeAsync();
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false } && !string.IsNullOrWhiteSpace(_newMessage))
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(_newMessage)) return;
        var content = _newMessage.Trim();
        _newMessage = "";
        await OnSendMessage.InvokeAsync(content);
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #313338;
}

.message-area-header {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.message-area-header h5 {
    margin: 0;
    color: #f2f3f5;
    font-size: 1rem;
    font-weight: 600;
}

.header-description {
    color: #80848e;
    font-size: 0.82rem;
    border-left: 1px solid #404249;
    padding-left: 10px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #80848e;
    font-size: 0.85rem;
}

.message-input-area {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 16px 20px;
    flex-shrink: 0;
}

.message-input {
    flex: 1;
    background-color: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 14px;
    color: #dbdee1;
    font-size: 0.95rem;
    font-family: inherit;
    resize: none;
    outline: none;
    min-height: 20px;
    max-height: 120px;
}

.message-input::placeholder {
    color: #6d6f78;
}

.send-btn {
    background-color: #5865f2;
    color: white;
    border: none;
    border-radius: 8px;
    padding: 10px 18px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    white-space: nowrap;
    transition: background-color 0.15s;
}

.send-btn:hover:not(:disabled) {
    background-color: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

