toolArgs.file_text:
@using sv_d6ddb3952d904867be27d6d70fce2d54.Services

<div class="thread-panel">
    <div class="thread-header">
        <h5>Thread</h5>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <div class="root-author">@RootMessage.Author</div>
            <div class="root-content">@RootMessage.Content</div>
        </div>

        <div class="thread-divider">
            <span>@ThreadMessages.Count @(ThreadMessages.Count == 1 ? "reply" : "replies")</span>
        </div>
    }

    <div class="thread-messages">
        @foreach (var message in ThreadMessages)
        {
            <MessageItem Message="message"
                         ThreadReplyCount="0"
                         OnOpenThread="EventCallback<int>.Empty"
                         OnReact="OnReact" />
        }
    </div>

    <div class="thread-input-area">
        <textarea class="thread-input"
                  rows="1"
                  placeholder="Reply…"
                  @bind="_replyText"
                  @onkeydown="HandleKeyDown" />
        <button class="reply-btn" disabled="@string.IsNullOrWhiteSpace(_replyText)" @onclick="SendReply">
            Reply
        </button>
    </div>
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }

    private string _replyText = "";

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false } && !string.IsNullOrWhiteSpace(_replyText))
        {
            await SendReply();
        }
    }

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(_replyText)) return;
        var content = _replyText.Trim();
        _replyText = "";
        await OnReply.InvokeAsync(content);
    }
}

