arguments.file_text:
@page "/chat"
@layout sv_d6ddb3952d904867be27d6d70fce2d54.Components.Chat.ChatLayout
@rendermode InteractiveServer
@using sv_d6ddb3952d904867be27d6d70fce2d54.Components.Chat
@using sv_d6ddb3952d904867be27d6d70fce2d54.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-panel">
        <ChannelList Channels="_channels"
                     SelectedChannelId="_selectedChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-panel @(_threadOpen ? "" : "main-panel-full")">
        @if (_selectedChannel is not null)
        {
            <MessageArea ChannelName="@_selectedChannel.Name"
                         ChannelDescription="@_selectedChannel.Description"
                         Messages="_messages"
                         ThreadSummaries="_threadSummaries"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadOlderMessages" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnReact="HandleReaction"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private int _selectedChannelId;
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];
    private bool _loadingMessages;
    private bool _hasMoreMessages = true;
    private const int PageSize = 50;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        if (_selectedChannelId == channelId) return;

        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _hasMoreMessages = true;
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];

        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the local unread count to zero
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task LoadMessages()
    {
        _loadingMessages = true;
        var loaded = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        if (loaded.Count < PageSize) _hasMoreMessages = false;

        _messages.InsertRange(0, loaded);
        BuildThreadSummaries();
        _loadingMessages = false;
    }

    private async Task LoadOlderMessages()
    {
        if (_loadingMessages || !_hasMoreMessages) return;
        await LoadMessages();
    }

    private void BuildThreadSummaries()
    {
        // Build thread summaries from messages that have replies
        var rootIds = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
        _threadSummaries = rootIds;
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
