.chat-layout {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    background-color: #313338;
    color: #dbdee1;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.sidebar-panel {
    width: 20%;
    min-width: 200px;
    max-width: 300px;
    flex-shrink: 0;
}

.main-panel {
    flex: 1;
    min-width: 0;
    /* When thread is open, main takes ~55% (flex handles it naturally alongside 25% thread panel) */
}

.main-panel-full {
    /* When no thread is open, main takes all remaining space after sidebar */
    flex: 1;
}

.thread-panel-container {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

.empty-state {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #80848e;
    font-size: 1.1rem;
}

